  ('higher and higher', 'higher and higher', 'en', 'read-v1', '{"word":"higher and higher","pos":"词块","ipa":"","gloss_cn":"越来越高","example":{"en":"In the middle of a cyclone the air is generally still, but the great pressure of the wind on every side of the house raised it up higher and higher, until it was at the very top of the cyclone; and there it remained and was carried miles and miles away as easily as you could carry a feather.","cn":"龙卷风的中心通常是平静的，但风从四面八方给房子巨大的压力，把房子抬得越来越高，直到它到了龙卷风的最顶端；房子就留在那里，被带走了很远很远，就像你拿起一片羽毛一样轻松。"},"note":"表示持续上升。","kind":"chunk","src_seqs":[44]}'::jsonb),
  ('at first', 'at first', 'en', 'read-v1', '{"word":"at first","pos":"词块","ipa":"","gloss_cn":"起初，一开始","example":{"en":"Once Toto got too near the open trap door, and fell in; and at first the little girl thought she had lost him.","cn":"有一次，托托离打开的活板门太近，掉了进去；小女孩一开始以为把它弄丢了。"},"note":"表示在最初的时候。","kind":"chunk","src_seqs":[49]}'::jsonb),
  ('got over', 'got over', 'en', 'read-v1', '{"word":"got over","pos":"词块","ipa":"","gloss_cn":"克服，恢复","example":{"en":"Hour after hour passed away, and slowly Dorothy got over her fright; but she felt quite lonely, and the wind shrieked so loudly all about her that she nearly became deaf.","cn":"一个小时又一个小时过去了，多萝西慢慢地不再那么害怕了；但她感觉很孤单，风在她身边大声呼啸，她差点被震聋了。"},"note":"表示从某种不愉快或困难中恢复过来。","kind":"chunk","src_seqs":[52]}'::jsonb),
  ('in spite of', 'in spite of', 'en', 'read-v1', '{"word":"in spite of","pos":"词块","ipa":"","gloss_cn":"尽管，不顾","example":{"en":"In spite of the swaying of the house and the wailing of the wind, Dorothy soon closed her eyes and fell fast asleep.","cn":"尽管房子还在摇晃，风还在呼啸，多萝西很快就闭上眼睛，睡着了。"},"note":"表示不顾某事，尽管有某事。","kind":"chunk","src_seqs":[55]}'::jsonb),
