  ('bark at', 'bark at', 'en', 'read-v1', '{"word":"bark at","pos":"词块","ipa":"","gloss_cn":"对...吠叫","example":{"en":"Toto ran over to the trees and began to bark at the birds sitting there.","cn":"托托跑到树林那边，开始对着停在那里的鸟儿叫。"},"note":"形容狗对着某物或某人发出叫声。","kind":"chunk","src_seqs":[179]}'::jsonb),
  ('help out', 'help out', 'en', 'read-v1', '{"word":"help out","pos":"词块","ipa":"","gloss_cn":"帮助完善/补充","example":{"en":"Dorothy went to get him, and saw such delicious fruit hanging from the branches that she gathered some of it, finding it just what she wanted to help out her breakfast.","cn":"多萝西去叫它回来，看到了树枝上挂着好多好吃的水果，于是她摘了一些，发现这正是她早餐想吃的。"},"note":"作为短语动词，表示协助或补充以完成某事。","kind":"chunk","src_seqs":[180]}'::jsonb),
