  ('just the thing', 'just the thing', 'en', 'read-v1', '{"word":"just the thing","pos":"词块","ipa":"","gloss_cn":"正是所需要的东西","example":{"en":"“They would be just the thing to take a long walk in, for they could not wear out.”","cn":"“穿着它们走远路最好不过了，因为它们不会穿坏。”"},"note":"惯用表达，指完全符合需求或恰到好处。","kind":"chunk","src_seqs":[191]}'::jsonb),
  ('wear out', 'wear out', 'en', 'read-v1', '{"word":"wear out","pos":"词块","ipa":"","gloss_cn":"磨损，穿坏","example":{"en":"“They would be just the thing to take a long walk in, for they could not wear out.”","cn":"“穿着它们走远路最好不过了，因为它们不会穿坏。”"},"note":"短语动词，指物品因使用而损坏或变旧。","kind":"chunk","src_seqs":[191]}'::jsonb),
