  ('awakened from his sleep', 'awakened from his sleep', 'en', 'read-v1', '{"word":"awakened from his sleep","pos":"词块","ipa":"","gloss_cn":"从睡梦中醒来","example":{"en":"And then they scampered in all directions, for Toto had awakened from his sleep, and seeing all these mice around him he gave one bark of delight and jumped right into the middle of the group.","cn":"然后它们四处跑开，因为托托醒了。他看到身边有这么多老鼠，就高兴地叫了一声，跳进了老鼠群里。"},"note":"强搭配 ''awaken from sleep'' 意为“从睡梦中醒来”。","kind":"chunk","src_seqs":[762]}'::jsonb),
  ('jumped right into the middle of', 'jumped right into the middle of', 'en', 'read-v1', '{"word":"jumped right into the middle of","pos":"词块","ipa":"","gloss_cn":"跳进了…中间","example":{"en":"And then they scampered in all directions, for Toto had awakened from his sleep, and seeing all these mice around him he gave one bark of delight and jumped right into the middle of the group.","cn":"然后它们四处跑开，因为托托醒了。他看到身边有这么多老鼠，就高兴地叫了一声，跳进了老鼠群里。"},"note":"固定表达 ''in the middle of'' 意为“在……中间”。","kind":"chunk","src_seqs":[762]}'::jsonb),
  ('saw no harm in it', 'saw no harm in it', 'en', 'read-v1', '{"word":"saw no harm in it","pos":"词块","ipa":"","gloss_cn":"觉得这没什么不对","example":{"en":"Toto had always loved to chase mice when he lived in Kansas, and he saw no harm in it.","cn":"托托在堪萨斯生活的时候，就一直喜欢追老鼠，他觉得这没什么不对。"},"note":"固定表达 ''see no harm in something'' 意为“认为某事无害，不觉得有什么不妥”。","kind":"chunk","src_seqs":[763]}'::jsonb),
  ('held him tight', 'held him tight', 'en', 'read-v1', '{"word":"held him tight","pos":"词块","ipa":"","gloss_cn":"紧紧地抱着他","example":{"en":"But the Tin Woodman caught the dog in his arms and held him tight, while he called to the mice, “Come back!","cn":"但是铁皮人把狗抱在怀里，紧紧地抱着，同时他对老鼠们喊道：“回来！"},"note":"强搭配 ''hold tight'' 意为“抓紧，抱紧”。","kind":"chunk","src_seqs":[764]}'::jsonb),
