  ('lined with', 'lined with', 'en', 'read-v1', '{"word":"lined with","pos":"词块","ipa":"","gloss_cn":"两旁是","example":{"en":"The streets were lined with beautiful houses all built of green marble and studded everywhere with sparkling emeralds.","cn":"街道两旁都是漂亮的房子，它们全是用绿色大理石建成的，上面还镶满了闪闪发光的绿宝石。"},"note":"表示某物排列在另一物的两侧。","kind":"chunk","src_seqs":[914]}'::jsonb),
  ('ran away', 'ran away', 'en', 'read-v1', '{"word":"ran away","pos":"词块","ipa":"","gloss_cn":"跑开","example":{"en":"They looked at Dorothy and her strangely assorted company with wondering eyes, and the children all ran away and hid behind their mothers when they saw the Lion; but no one spoke to them.","cn":"他们好奇地看着 多萝西 和她那群奇奇怪怪的同伴。当孩子们看到 狮子 时，都跑开躲到妈妈身后了；但没有人跟他们说话。"},"note":"指逃跑或迅速离开。","kind":"chunk","src_seqs":[918]}'::jsonb),
  ('of all sorts', 'of all sorts', 'en', 'read-v1', '{"word":"of all sorts","pos":"词块","ipa":"","gloss_cn":"各种各样的","example":{"en":"Green candy and green pop-corn were offered for sale, as well as green shoes, green hats, and green clothes of all sorts.","cn":"有绿色的糖果、绿色的爆米花在卖，还有绿色的鞋子、绿色的帽子和各种各样的绿色衣服。"},"note":"指种类繁多。","kind":"chunk","src_seqs":[920]}'::jsonb),
  ('demand to see', 'demand to see', 'en', 'read-v1', '{"word":"demand to see","pos":"词块","ipa":"","gloss_cn":"要求见","example":{"en":"“Here are strangers,” said the Guardian of the Gates to him, “and they demand to see the Great Oz.”","cn":"“这里有陌生人，”城门守卫 对他说，“他们想见大巫师 奥兹大王。”"},"note":"指强烈要求见到某人。","kind":"chunk","src_seqs":[926]}'::jsonb),
  ('carry your message', 'carry your message', 'en', 'read-v1', '{"word":"carry your message","pos":"词块","ipa":"","gloss_cn":"传达你的消息","example":{"en":"“Step inside,” answered the soldier, “and I will carry your message to him.”","cn":"“请进，”士兵回答，“我会把你们的话告诉他的。”"},"note":"指将信息传递给某人。","kind":"chunk","src_seqs":[927]}'::jsonb),
  ('make yourselves comfortable', 'make yourselves comfortable', 'en', 'read-v1', '{"word":"make yourselves comfortable","pos":"词块","ipa":"","gloss_cn":"请随意","example":{"en":"“Please make yourselves comfortable while I go to the door of the Throne Room and tell Oz you are here.”","cn":"“请大家舒服地坐着，我这就去宝座厅门口，告诉 奥兹大王 你们来了。”"},"note":"指让某人感到放松和自在。","kind":"chunk","src_seqs":[930]}'::jsonb),
  ('grant you an audience', 'grant you an audience', 'en', 'read-v1', '{"word":"grant you an audience","pos":"词块","ipa":"","gloss_cn":"接见你","example":{"en":"He said he will grant you an audience, if you so desire; but each one of you must enter his presence alone, and he will admit but one each day.","cn":"他说如果你想见他，他会让你进去。不过你们每个人都得单独进去，而且他一天只让一个人进去。"},"note":"指允许某人会见高层人物。","kind":"chunk","src_seqs":[936]}'::jsonb),
  ('rest in comfort', 'rest in comfort', 'en', 'read-v1', '{"word":"rest in comfort","pos":"词块","ipa":"","gloss_cn":"舒适地休息","example":{"en":"Therefore, as you must remain in the Palace for several days, I will have you shown to rooms where you may rest in comfort after your journey.”","cn":"所以，你们得在宫殿里住几天。我会让人带你们去房间，这样你们就能好好休息了，因为你们赶了很远的路。”"},"note":"指在舒适的环境中休息。","kind":"chunk","src_seqs":[937]}'::jsonb),
  ('said good-bye to', 'said good bye to', 'en', 'read-v1', '{"word":"said good-bye to","pos":"词块","ipa":"","gloss_cn":"向...告别","example":{"en":"So Dorothy said good-bye to all her friends except Toto, and taking the dog in her arms followed the green girl through seven passages and up three flights of stairs until they came to a room at the front of the Palace.","cn":"于是，多萝西跟所有朋友说了再见，只留下托托。她抱着小狗，跟着绿衣女孩穿过七条走廊，又走了三段楼梯，终于来到了宫殿前面的一间房间。"},"note":"指与某人说再见。","kind":"chunk","src_seqs":[941]}'::jsonb),
  ('in the world', 'in the world', 'en', 'read-v1', '{"word":"in the world","pos":"词块","ipa":"","gloss_cn":"世界上","example":{"en":"It was the sweetest little room in the world, with a soft comfortable bed that had sheets of green silk and a green velvet counterpane.","cn":"这是世界上最可爱的小房间了！床又软又舒服，铺着绿色的丝绸床单和绿色的天鹅绒被子。"},"note":"用于强调事物的最高程度。","kind":"chunk","src_seqs":[942]}'::jsonb),
  ('full of', 'full of', 'en', 'read-v1', '{"word":"full of","pos":"词块","ipa":"","gloss_cn":"充满","example":{"en":"When Dorothy had time to open these books she found them full of queer green pictures that made her laugh, they were so funny.","cn":"多萝西有空打开这些书的时候，发现里面都是奇怪的绿色图画，逗得她哈哈大笑，太好玩了。"},"note":"指被某物完全填满。","kind":"chunk","src_seqs":[945]}'::jsonb),
  ('send for you', 'send for you', 'en', 'read-v1', '{"word":"send for you","pos":"词块","ipa":"","gloss_cn":"派人来叫你","example":{"en":"Oz will send for you tomorrow morning.”","cn":"奥兹大王明天早上会派人来叫你。”"},"note":"指派人去接或召唤某人。","kind":"chunk","src_seqs":[948]}'::jsonb),
  ('wasted on', 'wasted on', 'en', 'read-v1', '{"word":"wasted on","pos":"词块","ipa":"","gloss_cn":"浪费在...身上","example":{"en":"Of course this politeness was wasted on the Scarecrow; for when he found himself alone in his room he stood stupidly in one spot, just within the doorway, to wait till morning.","cn":"当然，这份好心对稻草人来说一点用都没有。因为他发现自己一个人在房间里时，就傻傻地站在门口，一直等到天亮。"},"note":"指对某人或某事不起作用，白费。","kind":"chunk","src_seqs":[951]}'::jsonb),
  ('make sure', 'make sure', 'en', 'read-v1', '{"word":"make sure","pos":"词块","ipa":"","gloss_cn":"确保","example":{"en":"The Tin Woodman lay down on his bed from force of habit, for he remembered when he was made of flesh; but not being able to sleep, he passed the night moving his joints up and down to make sure they kept in good working order.","cn":"铁皮人习惯性地躺在床上，因为他记得自己以前是肉做的。但他睡不着，只好整晚不停地动来动去，检查自己的关节有没有坏掉。"},"note":"指核实或确定某事。","kind":"chunk","src_seqs":[953]}'::jsonb),
  ('shut up in', 'shut up in', 'en', 'read-v1', '{"word":"shut up in","pos":"词块","ipa":"","gloss_cn":"关在...里","example":{"en":"The Lion would have preferred a bed of dried leaves in the forest, and did not like being shut up in a room; but he had too much sense to let this worry him, so he sprang upon the bed and rolled himself up like a cat and purred himself asleep in a minute.","cn":"狮子更喜欢森林里用干树叶做的床，不喜欢被关在房间里。但他很聪明，没让自己烦恼。所以他跳到床上，像猫一样卷成一团，很快就舒服地睡着了。"},"note":"指被困在某个封闭空间内。","kind":"chunk","src_seqs":[954]}'::jsonb),
  ('the next morning', 'the next morning', 'en', 'read-v1', '{"word":"the next morning","pos":"词块","ipa":"","gloss_cn":"第二天早上","example":{"en":"The next morning, after breakfast, the green maiden came to fetch Dorothy, and she dressed her in one of the prettiest gowns, made of green brocaded satin.","cn":"第二天早上，吃过早饭后，绿衣女孩来接多萝西。她给多萝西穿上了一件最漂亮的绿色丝绸裙子。"},"note":"指紧接着的那个早上。","kind":"chunk","src_seqs":[955]}'::jsonb),
  ('had nothing to do but', 'had nothing to do but', 'en', 'read-v1', '{"word":"had nothing to do but","pos":"词块","ipa":"","gloss_cn":"除了...无事可做","example":{"en":"These people had nothing to do but talk to each other, but they always came to wait outside the Throne Room every morning, although they were never permitted to see Oz.","cn":"这些人除了聊天没什么事可做，但他们每天早上都会来宝座室外面等着，虽然他们从来都不能见到奥兹大王。"},"note":"表示别无选择或别无他事可做。","kind":"chunk","src_seqs":[958]}'::jsonb),
  ('looked like', 'looked like', 'en', 'read-v1', '{"word":"looked like","pos":"词块","ipa":"","gloss_cn":"长什么样","example":{"en":"Then he asked me what you looked like, and when I mentioned your silver shoes he was very much interested.","cn":"后来他问你长什么样，当我提到你的银鞋时，他可感兴趣啦。"},"note":"指外貌看起来像什么。","kind":"chunk","src_seqs":[964]}'::jsonb),
  ('could not help it', 'could not help it', 'en', 'read-v1', '{"word":"could not help it","pos":"词块","ipa":"","gloss_cn":"情不自禁","example":{"en":"“That just happened,” returned Dorothy simply; “I could not help it.”","cn":"“那只是碰巧发生的，” 多萝西 简单地说，“我控制不了。”"},"note":"指无法控制自己的行为或感受。","kind":"chunk","src_seqs":[998]}'::jsonb),
  ('pay for', 'pay for', 'en', 'read-v1', '{"word":"pay for","pos":"词块","ipa":"","gloss_cn":"付费购买","example":{"en":"In this country everyone must pay for everything he gets.","cn":"在这个国家，每个人得到东西都要付出代价。"},"note":"指为某物或某事支付费用。","kind":"chunk","src_seqs":[1001]}'::jsonb),
  ('no hope for me', 'no hope for me', 'en', 'read-v1', '{"word":"no hope for me","pos":"词块","ipa":"","gloss_cn":"对我没有希望","example":{"en":"“There is no hope for me,” she said sadly, “for Oz will not send me home until I have killed the Wicked Witch of the West; and that I can never do.”","cn":"“我没有希望了，”她伤心地说，“因为 奥兹大王 不会送我回家，除非我杀死了 西方坏女巫；而那是我永远也做不到的。”"},"note":"表示对某事不抱希望。","kind":"chunk","src_seqs":[1017]}'::jsonb),
  ('cried herself to sleep', 'cried herself to sleep', 'en', 'read-v1', '{"word":"cried herself to sleep","pos":"词块","ipa":"","gloss_cn":"哭着睡着了","example":{"en":"Her friends were sorry, but could do nothing to help her; so Dorothy went to her own room and lay down on the bed and cried herself to sleep.","cn":"她的朋友们都很难过，但帮不了她什么；于是 多萝西 回到自己的房间，躺在床上，哭着睡着了。"},"note":"指哭泣直到入睡。","kind":"chunk","src_seqs":[1018]}'::jsonb),
