  ('make slaves of', 'make slaves of', 'en', 'read-v1', '{"word":"make slaves of","pos":"词块","ipa":"","gloss_cn":"把…变成奴隶","example":{"en":"“No one has ever destroyed her before, so I naturally thought she would make slaves of you, as she has of the rest.","cn":"“以前没人打败过她，我以为她会把你们变成奴隶，就像对其他人那样。"},"note":"指强迫某人或群体成为奴隶。","kind":"chunk","src_seqs":[1111]}'::jsonb),
  ('take care', 'take care', 'en', 'read-v1', '{"word":"take care","pos":"词块","ipa":"","gloss_cn":"小心","example":{"en":"But take care; for she is wicked and fierce, and may not allow you to destroy her.","cn":"不过你们要小心哦！她很坏很凶，可能不会让你们打败她。"},"note":"提醒对方小心谨慎。","kind":"chunk","src_seqs":[1112]}'::jsonb),
