  ('fell asleep', 'fell asleep', 'en', 'read-v1', '{"word":"fell asleep","pos":"词块","ipa":"","gloss_cn":"睡着了","example":{"en":"In the afternoon the sun shone hot in their faces, for there were no trees to offer them shade; so that before night Dorothy and Toto and the Lion were tired, and lay down upon the grass and fell asleep, with the Woodman and the Scarecrow keeping watch.","cn":"下午，太阳晒得他们的脸热热的，因为这里没有大树遮荫。所以天黑前，多萝西、托托和狮子都累了，躺在草地上睡着了。铁皮人和稻草人帮他们守夜。"},"note":"表示进入睡眠状态。","kind":"chunk","src_seqs":[1119]}'::jsonb),
  ('keeping watch', 'keeping watch', 'en', 'read-v1', '{"word":"keeping watch","pos":"词块","ipa":"","gloss_cn":"守夜/放哨","example":{"en":"In the afternoon the sun shone hot in their faces, for there were no trees to offer them shade; so that before night Dorothy and Toto and the Lion were tired, and lay down upon the grass and fell asleep, with the Woodman and the Scarecrow keeping watch.","cn":"下午，太阳晒得他们的脸热热的，因为这里没有大树遮荫。所以天黑前，多萝西、托托和狮子都累了，躺在草地上睡着了。铁皮人和稻草人帮他们守夜。"},"note":"指保持警惕，看守。","kind":"chunk","src_seqs":[1119]}'::jsonb),
