  ('covered from top to bottom', 'covered from top to bottom', 'en', 'read-v1', '{"word":"covered from top to bottom","pos":"词块","ipa":"","gloss_cn":"从头到脚覆盖着；全身覆盖","example":{"en":"The four travelers passed through the rest of the forest in safety, and when they came out from its gloom saw before them a steep hill, covered from top to bottom with great pieces of rock.","cn":"四个旅行者安全地走出了森林。当他们走出阴暗的森林时，看到前面有一座陡峭的山，山上从头到脚都是大块大块的石头。"},"note":"形容某物被完全覆盖。","kind":"chunk","src_seqs":[1973]}'::jsonb),
  ('get over', 'get over', 'en', 'read-v1', '{"word":"get over","pos":"词块","ipa":"","gloss_cn":"翻越；克服（困难）","example":{"en":"“That will be a hard climb,” said the Scarecrow, “but we must get over the hill, nevertheless.”","cn":"“那会很难爬，”稻草人说，“但我们还是得翻过这座山。”"},"note":"可指越过障碍物，也可指从疾病或困难中恢复。","kind":"chunk","src_seqs":[1974]}'::jsonb),
  ('keep back', 'keep back', 'en', 'read-v1', '{"word":"keep back","pos":"词块","ipa":"","gloss_cn":"后退；阻止靠近","example":{"en":"They had nearly reached the first rock when they heard a rough voice cry out, “Keep back!”","cn":"他们快走到第一块大石头那里时，听到一个粗鲁的声音喊道：“别过来！”"},"note":"可指自己后退，也可指阻止某人或某物靠近。","kind":"chunk","src_seqs":[1976]}'::jsonb),
  ('belongs to', 'belongs to', 'en', 'read-v1', '{"word":"belongs to","pos":"词块","ipa":"","gloss_cn":"属于","example":{"en":"Then a head showed itself over the rock and the same voice said, “This hill belongs to us, and we don’t allow anyone to cross it.”","cn":"然后，一个脑袋从石头后面露出来，那个声音又说：“这座山是我们的，我们不让任何人过。”"},"note":"表示所有关系。","kind":"chunk","src_seqs":[1978]}'::jsonb),
